// Evitar envíos duplicados mientras hay un registro en tránsito
const lock = flow.get("envioRegistro17EnProceso");
if (lock) {
    const lockAgeMs = Date.now() - (lock.ts || 0);
    if (lockAgeMs < 30000) {
        return null;
    }
    // Liberar locks antiguos para permitir reintentos
    flow.set("envioRegistro17EnProceso", null);
}

// Obtener la variable global "datos17"
var datos17 = global.get("datos17");

// Verificar si la variable global tiene el formato esperado
if (datos17 && datos17.dataItems && Array.isArray(datos17.dataItems)) {

    // Recorrer los elementos de dataItems
    for (let item of datos17.dataItems) {
        if (item.data && Array.isArray(item.data)) {

            // Recorrer los datos dentro del array "data"
            for (let subItem of item.data) {
                if (subItem.data && Array.isArray(subItem.data)) {

                    // Recorrer los registros de datos buscando el primero que cumpla con los criterios
                    for (let registro of subItem.data) {
                        if (registro.estado === "finalizado" && registro.procesado === "pendiente") {

                            // Crear payload limpio para la solicitud HTTP
                            const { procesado, ...salida } = registro;

                            // Bloquear nuevos envíos hasta recibir respuesta del request HTTP
                            const clave = `${salida.maquina}|${salida.timeRangeInicio}|${salida.timeRangeFinal}`;
                            flow.set("envioRegistro17EnProceso", { clave, ts: Date.now() });

                            // Asignarlo a msg.payload para enviarlo en la solicitud HTTP
                            msg.payload = salida;
                            msg.previo = { payload: salida, clave };

                            // Salir del ciclo después de encontrar el primer registro
                            return msg;
                        }
                    }
                }
            }
        }
    }
}

// Si no se encuentra ningún registro que cumpla con los criterios, no enviar mensaje
return null;

// Obtener el mensaje devuelto por el servidor
var payload = msg.payload;
var lock = flow.get("envioRegistro17EnProceso");

if (payload.message === "ok") {
    // Obtener la variable global "datos17"
    var datos17 = global.get("datos17");

    // Verificar si la variable global tiene el formato esperado
    if (datos17 && datos17.dataItems && Array.isArray(datos17.dataItems)) {

        // Recorrer los elementos de dataItems
        for (let item of datos17.dataItems) {
            if (item.data && Array.isArray(item.data)) {

                // Recorrer los datos dentro del array "data"
                for (let subItem of item.data) {
                    if (subItem.data && Array.isArray(subItem.data)) {

                        // Encontrar el registro enviado (lo que estaba en msg.previo.payload)
                        let index = subItem.data.findIndex(registro =>
                            registro.maquina === msg.previo.payload.maquina &&
                            registro.timeRangeInicio === msg.previo.payload.timeRangeInicio &&
                            registro.timeRangeFinal === msg.previo.payload.timeRangeFinal
                        );

                        // Si se encuentra el registro, eliminarlo
                        if (index !== -1) {
                            subItem.data.splice(index, 1);

                            // Guardar la variable global actualizada
                            global.set("datos17", datos17);

                            // Liberar bloqueo solo tras actualización exitosa
                            if (lock && msg.previo && msg.previo.clave && lock.clave === msg.previo.clave) {
                                flow.set("envioRegistro17EnProceso", null);
                            }

                            // Enviar un mensaje indicando que la variable global ha sido actualizada
                            node.send({ payload: "actualizado" });
                            return;
                        }
                    }
                }
            }
        }
    }

    // Si no se encuentra el registro, enviar un mensaje de error
    node.send({ payload: "error: registro no encontrado" });
} else {
    // Si la respuesta del servidor no es "ok", enviar un mensaje de error
    node.send({ payload: "error: respuesta del servidor no es ok" });
}
